const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const [a, b] = line.split(' ').map(Number);
    let c1 = 0, c2 = 0, c3 = 0;

    for (let i = 6; i > 0; i--) {
        const x = Math.abs(i - a);
        const y = Math.abs(i - b);

        if (x < y) {
            c1++;
        } else if (x > y) {
            c2++;
        } else {
            c3++;
        }
    }

    console.log(c1, c3, c2);
    rl.close();
});

